<div class="page-header"><div><span class="eyebrow">A MILESTONE YOU CAN POINT TO</span><h1>Progress worth celebrating.</h1><p>A record of the work you actually completed. Earned, never automatic.</p></div><span class="icon-tile orange"><?= icon('award',25) ?></span></div><div class="stack"><?php if($certificates): ?><?php foreach($certificates as $c): ?><article class="card certificate-card"><span class="icon-tile orange"><?= icon('award',30) ?></span><div><h3><?= e($c['path_title']) ?></h3><p>Issued <?= niceDate($c['issued_at']) ?> · <?= $c['revoked_at']?'Revoked':'Valid certificate' ?></p></div><a href="<?= e(route_url('/verify/' . ($c['identifier']))) ?>" class="btn btn-secondary btn-small">View & print <?= icon('arrow-up-right',15) ?></a></article><?php endforeach; ?><?php else: ?><div class="card"><?php emptyState('award','Your first milestone is ahead.','Finish a path’s required lessons, knowledge checks and accepted assignments to earn a certificate you can verify and share.','/my-learning','Back to my learning'); ?></div><?php endif; ?><?php if($enrolments): ?><section class="card card-pad"><div class="card-header"><div><h2>Something to work towards.</h2><p>Eligibility is checked against current, published requirements.</p></div></div><?php foreach($enrolments as $p): ?><div class="list-row"><div><h3><?= e($p['title']) ?></h3><p><?= $p['completed_at']?'Path completion recorded. Check certificate eligibility.':'Complete every required lesson, quiz and assignment.' ?></p></div><form action="<?= e(route_url('/api/certificates/' . ((int)$p['id']))) ?>" method="post" data-api><?= csrfField() ?><button class="btn btn-secondary btn-small">Check eligibility <?= icon('arrow-right',14) ?></button></form></div><?php endforeach; ?></section><?php endif; ?></div>
